def countOfSubstrings(S, K):
    char_count = {}
    count = 0
    distinct_count = 0

    # Initialize the first window
    for i in range(K):
        if S[i] not in char_count:
            char_count[S[i]] = 0
            distinct_count += 1
        char_count[S[i]] += 1

    # Check if the first window has exactly K-1 distinct characters
    if distinct_count == K - 1:
        count += 1

    # Slide the window
    for i in range(K, len(S)):
        # Remove the leftmost character from the window
        if char_count[S[i - K]] == 1:
            del char_count[S[i - K]]
            distinct_count -= 1
        else:
            char_count[S[i - K]] -= 1

